{
  "application": "ppt-generation",
  "case_id": "case-risingstars-js-2024",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 8,
    "audience": "frontend engineers and engineering managers tracking JavaScript ecosystem trends",
    "tone": "data-forward, technical, accessible"
  },
  "brief": {
    "title": "2024 JavaScript Rising Stars: Top Projects and Ecosystem Shifts",
    "one_liner": "A data-driven overview of the most-starred JavaScript projects in 2024, highlighting the dominance of shadcn/ui, the rise of htmx, and major framework evolutions.",
    "goal": "Equip the audience with a clear understanding of which JavaScript projects gained the most traction in 2024, why they succeeded, and what ecosystem trends to watch heading into 2025."
  },
  "slides": [
    {
      "id": "title-cover",
      "title": "2024 JavaScript Rising Stars: The Year's Hottest Projects by GitHub Stars",
      "objective": "Cover slide introducing the 9th edition of JavaScript Rising Stars, noting the methodology (GitHub stars added in 2024 from Best of JS curated list)."
    },
    {
      "id": "overall-top-10",
      "title": "shadcn/ui Leads Overall with +38k Stars, Followed by Excalidraw and AFFiNE",
      "objective": "Present a ranked bar chart or table of the top 10 most-starred projects overall, showing star counts. Emphasize the gap between #1 and the rest."
    },
    {
      "id": "shadcn-deep-dive",
      "title": "shadcn/ui: Copy-Paste Components Win for the Second Consecutive Year",
      "objective": "Detail shadcn/ui's year-over-year growth trajectory (N/A through 2022, 39.5k in 2023, 38.0k in 2024) using the yearly trend chart. Highlight key 2024 features: Charts, Themes, Blocks, Sidebar, new CLI with multi-framework support. Reference figure_1.jpg and figure_2.jpg for trend visuals."
    },
    {
      "id": "frontend-frameworks",
      "title": "htmx Overtakes React as #1 Front-end Framework by Stars Added",
      "objective": "Show the front-end frameworks ranking with htmx (+16.8k), React (+14.2k), Svelte (+6.1k), Vue (+5.9k), Angular (+3.5k). Explain htmx's HTML-extension philosophy and React 19's long-awaited release with Server Components."
    },
    {
      "id": "react-ecosystem",
      "title": "React Ecosystem: shadcn/ui, Excalidraw, and Payload Dominate",
      "objective": "Display the top 5 React ecosystem projects (shadcn/ui +38k, Excalidraw +27k, Payload +14.4k, Magic UI +13.2k, Next.js +12.1k). Discuss React's evolution toward a full-stack framework specification."
    },
    {
      "id": "vue-ecosystem",
      "title": "Vue Ecosystem Flourishes: Nuxt, PrimeVue, and Slidev Lead Growth",
      "objective": "Present the Vue ecosystem top 5 (Nuxt +6.2k, PrimeVue +5.4k, Slidev +4.7k, shadcn-vue +4.1k, VitePress +3.7k). Note Vue 3.5 reactivity rework and the alien-signals approach."
    },
    {
      "id": "emerging-themes",
      "title": "AI Tools, Desktop Apps, and Browser-Based Innovation Shape 2024",
      "objective": "Highlight cross-cutting themes: AI-powered projects (Flowise +14.5k, n8n +17k), desktop via Tauri (+15.9k), browser capabilities (PGlite, WebVM), and the BaaS trend (Supabase +14.5k). Use a thematic grouping visual."
    },
    {
      "id": "takeaways",
      "title": "Key Takeaways: What 2024 Tells Us About JavaScript's Future",
      "objective": "Summarize 4-5 actionable takeaways: (1) component ownership model wins over imports, (2) HTML-first approaches gain serious traction, (3) React is becoming a framework specification, (4) AI integration is now table stakes, (5) Vue's UI library ecosystem is a sign of maturity. End with forward-looking implications for 2025."
    }
  ]
}

